/// Error types for HTTPS-based protocols.
#[derive(Debug, Error)]
pub enum ProtocolError {
    #[error("an error occurred in an XPCOM call: {0}")]
    XpCom(#[from] nsresult),

    #[error("an error occurred during HTTP transport: {0}")]
    Http(#[from] moz_http::Error),

    /// If this error originates from sending a protocol request (as opposed to
    /// e.g. trying to authenticate against an OAuth2 server), it contains the
    /// values of the response's `WWW-Authenticate` headers. If the response
    /// does not include such headers, the inner value is `Some([])`.
    #[error("failed to authenticate")]
    Authentication(Option<Vec<String>>),

    #[error("an item was too large to process: {0}")]
    Size(usize),

    #[error("client has shut down")]
    ClientClosed,

    #[error("error while waiting for line to release: {0}")]
    OperationReceiver(#[from] RecvError),

    #[error("URL parse error: {0}")]
    UrlParse(#[from] ParseError),

    #[error("invalid header name: {0:?}")]
    InvalidHeaderValue(HeaderValue),

    #[error("operation queue error: {0}")]
    Queue(#[from] operation_queue::Error),

    #[error("an error occurred building the HTTP request: {0}")]
    HttpBuilder(#[from] http::Error),

    #[error("error in processing response: {message}")]
    Processing { message: String },
}

impl From<&ProtocolError> for nsresult {
    fn from(value: &ProtocolError) -> Self {
        match value {
            ProtocolError::XpCom(value) => *value,
            ProtocolError::Http(value) => value.into(),

            _ => nserror::NS_ERROR_UNEXPECTED,
        }
    }
